import{H as e,Q as t,ht as n,nt as r,tt as i}from"./chunks/framework.qcK96eCy.js";var a=JSON.parse(`{"title":"What is mcp-hub?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1788301578000}`),o={name:`guide/index.md`};function s(e,a,o,s,c,l){return n(),i(`div`,null,[...a[0]||=[r(`<h1 id="what-is-mcp-hub" tabindex="-1">What is mcp-hub? <a class="header-anchor" href="#what-is-mcp-hub" aria-label="Permalink to “What is mcp-hub?”">​</a></h1><p>mcp-hub serves many <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">Model Context Protocol</a> servers from <strong>one container</strong>, published over HTTPS for ChatGPT connectors, Claude (Web and Code), Mistral Le Chat, Cursor and any other Streamable-HTTP MCP client — behind a built-in OAuth 2.1 authorization server protected by a single password, with API tokens for clients that cannot do OAuth.</p><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to “The problem”">​</a></h2><p>Most MCP servers are stdio programs. They read JSON-RPC on stdin and write it on stdout, and they assume a client that starts them as a child process. That works beautifully on a laptop and not at all for a hosted client: ChatGPT connectors, Claude Web and Le Chat speak HTTP and expect OAuth.</p><p>The usual fix is to wrap each stdio server in its own auth proxy. That works, but the cost per server is real:</p><ul><li>a container image and a compose stack,</li><li>a hostname and a TLS certificate,</li><li>an OAuth authorization server with its own client registrations and its own state directory,</li><li>a firewall rule, a log stream, a monitoring entry and a backup path.</li></ul><p>Nine servers means nine of each. Every one of them has to be updated, scanned and re-authorized separately, and every one is a place where an authorization bug can hide.</p><h2 id="what-mcp-hub-does-instead" tabindex="-1">What mcp-hub does instead <a class="header-anchor" href="#what-mcp-hub-does-instead" aria-label="Permalink to “What mcp-hub does instead”">​</a></h2><p>One Node process holds all of it:</p>`,9),t(`figure`,{class:`hub-diagram`},[t(`svg`,{viewBox:`0 0 760 300`,xmlns:`http://www.w3.org/2000/svg`,role:`img`,"aria-labelledby":`before-after-title`},[t(`title`,{id:`before-after-title`},`Comparison: one auth proxy container per server versus a single mcp-hub container`),t(`defs`,null,[t(`marker`,{id:`arrow-ba`,viewBox:`0 0 10 10`,refX:`9`,refY:`5`,markerWidth:`7`,markerHeight:`7`,orient:`auto-start-reverse`},[t(`path`,{d:`M0 0 L10 5 L0 10 z`})])]),t(`text`,{x:`12`,y:`24`,class:`label-title`},`Before — one wrapper per server`),t(`text`,{x:`420`,y:`24`,class:`label-title`},`With mcp-hub`),t(`rect`,{class:`node`,x:`12`,y:`44`,width:`150`,height:`46`,rx:`8`}),t(`text`,{x:`87`,y:`66`,"text-anchor":`middle`,class:`label-mono`},`a.example.net`),t(`text`,{x:`87`,y:`82`,"text-anchor":`middle`,class:`label-muted`},`proxy + OAuth + server`),t(`rect`,{class:`node`,x:`12`,y:`102`,width:`150`,height:`46`,rx:`8`}),t(`text`,{x:`87`,y:`124`,"text-anchor":`middle`,class:`label-mono`},`b.example.net`),t(`text`,{x:`87`,y:`140`,"text-anchor":`middle`,class:`label-muted`},`proxy + OAuth + server`),t(`rect`,{class:`node`,x:`12`,y:`160`,width:`150`,height:`46`,rx:`8`}),t(`text`,{x:`87`,y:`182`,"text-anchor":`middle`,class:`label-mono`},`c.example.net`),t(`text`,{x:`87`,y:`198`,"text-anchor":`middle`,class:`label-muted`},`proxy + OAuth + server`),t(`text`,{x:`87`,y:`232`,"text-anchor":`middle`,class:`label-muted`},`…once per server`),t(`text`,{x:`87`,y:`252`,"text-anchor":`middle`,class:`label-muted`},`N images · N certificates`),t(`text`,{x:`87`,y:`270`,"text-anchor":`middle`,class:`label-muted`},`N logins to maintain`),t(`line`,{class:`edge edge-dashed`,x1:`360`,y1:`30`,x2:`360`,y2:`280`}),t(`rect`,{class:`node-accent`,x:`420`,y:`44`,width:`180`,height:`162`,rx:`12`}),t(`text`,{x:`510`,y:`70`,"text-anchor":`middle`,class:`label-title`},`mcp.example.net`),t(`text`,{x:`510`,y:`88`,"text-anchor":`middle`,class:`label-muted`},`one image · one certificate`),t(`text`,{x:`510`,y:`106`,"text-anchor":`middle`,class:`label-muted`},`one login`),t(`rect`,{class:`node`,x:`436`,y:`120`,width:`148`,height:`30`,rx:`6`}),t(`text`,{x:`510`,y:`140`,"text-anchor":`middle`,class:`label-mono`},`/hub`),t(`rect`,{class:`node`,x:`436`,y:`160`,width:`148`,height:`30`,rx:`6`}),t(`text`,{x:`510`,y:`180`,"text-anchor":`middle`,class:`label-mono`},`/<name>/mcp`),t(`rect`,{class:`node`,x:`640`,y:`52`,width:`104`,height:`34`,rx:`7`}),t(`text`,{x:`692`,y:`74`,"text-anchor":`middle`,class:`label-mono`},`server a`),t(`rect`,{class:`node`,x:`640`,y:`98`,width:`104`,height:`34`,rx:`7`}),t(`text`,{x:`692`,y:`120`,"text-anchor":`middle`,class:`label-mono`},`server b`),t(`rect`,{class:`node`,x:`640`,y:`144`,width:`104`,height:`34`,rx:`7`}),t(`text`,{x:`692`,y:`166`,"text-anchor":`middle`,class:`label-mono`},`server c`),t(`path`,{class:`edge`,d:`M604 132 C 620 132, 620 69, 636 69`,"marker-end":`url(#arrow-ba)`}),t(`path`,{class:`edge`,d:`M604 132 C 620 132, 620 115, 636 115`,"marker-end":`url(#arrow-ba)`}),t(`path`,{class:`edge`,d:`M604 132 C 620 132, 620 161, 636 161`,"marker-end":`url(#arrow-ba)`}),t(`text`,{x:`510`,y:`232`,"text-anchor":`middle`,class:`label-muted`},`one supervisor for every child`),t(`text`,{x:`510`,y:`252`,"text-anchor":`middle`,class:`label-muted`},`one OAuth state directory`),t(`text`,{x:`510`,y:`270`,"text-anchor":`middle`,class:`label-muted`},`one config file to edit`)]),t(`figcaption`,null,`N wrapper containers collapse into one process — the servers themselves are unchanged.`)],-1),r('<h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to “What you get”">​</a></h2><p><strong>Your existing config works.</strong> <code>/config/mcp.json</code> uses exactly Claude Code&#39;s <code>mcpServers</code> schema, <code>${VAR}</code> expansion included. Copy entries across without translating them. The one extra field, <code>&quot;hub&quot;: false</code>, is ignored by Claude Code, so the file stays interchangeable.</p><p><strong>Path-based routing.</strong> Each server is reachable at <code>/&lt;name&gt;</code> and <code>/&lt;name&gt;/mcp</code>. Register the ones you reach for daily as their own connectors.</p><p><strong>The <code>/hub</code> aggregate.</strong> Registering nine connectors means nine servers&#39; worth of tool schemas in the model&#39;s context before a single question is asked. <code>/hub</code> is one connector that exposes six meta-tools — <code>list_servers</code>, <code>list_tools</code>, <code>get_tool_schema</code>, <code>call_tool</code> — and lets the model page in only the schema it actually needs. Four schemas instead of N×tools.</p><p><strong>Client registration that does not need registering.</strong> The hub is its own OAuth 2.1 authorization server, and it takes the path the MCP specification now prefers: a client uses an HTTPS URL as its <code>client_id</code> and hosts its own <a href="/guide/client-registration">metadata document</a> there, including the keys it authenticates with. Nothing is issued, nothing expires, and a client that reinstalls is still the same client. RFC 7591 dynamic registration stays advertised beside it, so older clients keep working — and one setting retires it when you no longer need it.</p><p><strong>Real supervision.</strong> Children start at boot, get pinged every 60 seconds and are restarted with exponential backoff when they die. A server that is down answers <code>503</code> on its path and shows up in <code>/health</code> — it does not hang.</p><p><strong>Hot reload.</strong> Editing <code>mcp.json</code> starts, stops or restarts exactly the servers whose entries changed. Everything else keeps its connections.</p><p><strong>Stateless transport.</strong> No session state is kept between requests, so a client that reconnects without closing its previous session — which claude.ai does, roughly every five minutes — cannot leak processes or memory.</p><p><strong>Both MCP revisions, on every endpoint.</strong> <code>2026-07-28</code> and <code>2025-11-25</code>; the client picks and cannot tell from the answers which one it got. On the 2026 revision a child server&#39;s <a href="/guide/elicitation">question reaches the person</a> at the far end, which is the one thing a gateway used to take away from servers like <code>smtp-mcp</code> and <code>imap-mcp</code>.</p><p><strong>Changes reach the client that asked, whichever era the server speaks.</strong> A client opens a <a href="/guide/subscriptions"><code>subscriptions/listen</code></a> stream and hears when a child&#39;s tools, prompts or resources change. Upstream the hub asks each child the way that child understands — <code>subscriptions/listen</code> to a 2026 server, <code>resources/subscribe</code> to a 2025 one — so the era gap is the gateway&#39;s problem rather than either end&#39;s. Most MCP servers in the wild are still on the older revision, which is exactly when this matters.</p><p><strong>Light enough for a Raspberry Pi.</strong> A stated project goal: one Node process, no database — state is one JSON file plus an Ed25519 key under <code>/data</code> — a six runtime dependencies, and multi-arch images (<code>amd64</code>/<code>arm64</code>). The stateless transport and the missing database are not accidents; they are what keeps the hub comfortable on a single-board computer.</p><h2 id="what-it-is-not" tabindex="-1">What it is not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to “What it is not”">​</a></h2><ul><li><strong>Not a sandbox.</strong> Every stdio server configured in the hub container runs as the same operating-system user as the hub and can read its mounted files and environment. Only run stdio packages you trust; put anything else in its own container and connect it as a remote server. See <a href="/guide/security">Security</a>.</li><li><strong>Not a notification bridge for <code>2025-11-25</code> clients.</strong> Change notifications are carried on <code>2026-07-28</code>, where the client opens the stream and the state is the open response. The older revision delivers them unsolicited on a channel the stateless transport does not keep, so the hub does not offer them there — and says so in its capabilities rather than announcing something that will not arrive.</li><li><strong>Not a multi-user system.</strong> There is one password. Anyone who has it can approve a client and reach every server the hub exposes.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/getting-started">Getting started</a> — a working deployment</li><li><a href="/guide/configuration">Configuration</a> — writing your <code>mcp.json</code></li><li><a href="/guide/client-registration">Client registration</a> — how clients get a <code>client_id</code></li><li><a href="/guide/architecture">Architecture</a> — what happens inside</li><li><a href="/guide/comparison">Comparison</a> — when something else fits better</li></ul>',15)]])}var c=e(o,[[`render`,s]]);export{a as __pageData,c as default};